class Solution(object):
    def findMinFibonacciNumbers(self, k):
        """
        :type k: int
        :rtype: int
        """
        nums = [1, 1]
        while nums[-1] < k:
            nums.append(nums[-1] + nums[-2])
        p = len(nums) - 1
        ans = 0
        while k > 0:
            if nums[p] > k:
                p -= 1
            else:
                ans += k // nums[p]
                k = k % nums[p]
        return ans

